            Optional.of(ImmutableSet.of(Paths.get("foo/testfoo.m"))),
            Optional.empty(),
            Optional.empty(),
            false,
            "BUCK");
    assertEquals(ImmutableSet.of("//foo:xctest"), matchingBuildRules.keySet());
