package com.google.zxing.client.result;

import com.codename1.util.regex.RE;
import com.google.zxing.Result;

/**
 * Tries to parse results that are a URI of some kind.
 * 
 * @author <NAME>
 */
public final class URIResultParser extends ResultParser {

	// Was no ^ and $ to indicate whole string
	private static final RE ALLOWED_URI_CHARS_PATTERN = new RE("^[-._~:/?#\\[\\]@!$&'()*+,;=%A-Za-z0-9]+$");
	private static final RE USER_IN_HOST = new RE(":/*([^/@]+)@[^/]+");
	// See http://www.ietf.org/rfc/rfc2396.txt; // Added ^ to indicate start of
	// string
	private static final RE URL_WITH_PROTOCOL_PATTERN = new RE("^[a-zA-Z][a-zA-Z0-9+-.]+:");
	// Added ^ to indicate start of string
	private static final RE URL_WITHOUT_PROTOCOL_PATTERN = new RE("^([a-zA-Z0-9\\-]+\\.){1,6}[a-zA-Z]{2,}" +
	// host name elements; allow up to say 6 domain elements
			"(:\\d{1,5})?" + // maybe port
			"(/|\\?|$)"); // query, path or nothing

	@Override
	public URIParsedResult parse(Result result) {
		String rawText = getMassagedText(result);
		// We specifically handle the odd "URL" scheme here for simplicity and add "URI"
		// for fun
		// Assume anything starting this way really means to be a URI
		if (rawText.startsWith("URL:") || rawText.startsWith("URI:")) {
			return new URIParsedResult(rawText.substring(4).trim(), null);
		}
		rawText = rawText.trim();
		if (!isBasicallyValidURI(rawText) || isPossiblyMaliciousURI(rawText)) {
			return null;
		}
		return new URIParsedResult(rawText, null);
	}

	/**
	 * @return true if the URI contains suspicious patterns that may suggest it
	 *         intends to mislead the user about its true nature. At the moment this
	 *         looks for the presence of user/password syntax in the host/authority
	 *         portion of a URI which may be used in attempts to make the URI's host
	 *         appear to be other than it is. Example:
	 *         http://yourbank.com@phisher.com This URI connects to phisher.com but
	 *         may appear to connect to yourbank.com at first glance.
	 */
	static boolean isPossiblyMaliciousURI(String uri) {
		return !ALLOWED_URI_CHARS_PATTERN.match(uri) || USER_IN_HOST.match(uri);
		// return !ALLOWED_URI_CHARS_PATTERN.matcher(uri).matches() ||
		// USER_IN_HOST.matcher(uri).find();

	}

	static boolean isBasicallyValidURI(String uri) {
		if (uri.contains(" ")) {
			// Quick hack check for a common case
			return false;
		}
		boolean found = URL_WITH_PROTOCOL_PATTERN.match(uri);
		if (found) { // match at start only
			return true;
		}
		found = URL_WITHOUT_PROTOCOL_PATTERN.match(uri);
		return found;
	}

}

