package com.joewang.repast.utils;

import java.util.Random;

/**
 * @description:
 *      文件名处理类
 * @author: <NAME>
 * @date: 2020-03-10
 */
public class FileNameUtil {
    /*
     * @desc: 生成文件名方法
     * @author: <NAME>
     * @date: 2020/3/10
     * @param: [userId]
     * @return: java.lang.String
     */
    public static String getFileName(String token) {
        // 1.获取当前时间的毫秒数
        long currentTimeMillis = System.currentTimeMillis();
        // 2.创建Random对象
        Random random = new Random();
        // 3.随机0-999之间的数字
        Integer randomNum = random.nextInt(999);
        // 4.最终的文件名
        //currentTimeMillis+userId+randomNum
        // %:占位符 03:三位 d:数字 --->如果随机出的数字没有达到三位03，默认自动往前面补0
        String fileName = currentTimeMillis + token + String.format("%03d", randomNum);
        // 5.返回文件名
        return fileName;
    }
}

