import java.io.*;


/**
 * Created by ienovo on 2016/8/11.
 */

//
public class FTPfUpAndDownUtil {

    /**
     *      * 上传文件（可供Action/Controller层使用）
     *      * @param hostname FTP服务器地址
     *      * @param port   FTP服务器端口号
     *      * @param username   FTP登录帐号
     *      * @param password   FTP登录密码
     *      * @param pathname   FTP服务器保存目录
     *      * @param fileName   上传到FTP服务器后的文件名称
     *      * @param inputStream 输入文件流
     *      * @return
     *      
     */
    public static boolean uploadFile(String hostname, int port, String username,
                                     String password, String pathname, String fileName, InputStream inputStream) {
        boolean flag = false;
        FTPClient ftpClient = new FTPClient();
        //ftpClient.setControlEncoding("UTF-8");
        try {
            //连接FTP服务器
            ftpClient.connect(hostname, port);
            //登录FTP服务器
            ftpClient.login(username, password);
            //是否成功登录FTP服务器
            int replyCode = ftpClient.getReplyCode();
            if (!FTPReply.isPositiveCompletion(replyCode)) {
                return flag;
            }

            ftpClient.setFileType(FTPClient.BINARY_FILE_TYPE);
            ftpClient.makeDirectory(pathname);
            ftpClient.changeWorkingDirectory(pathname);
            ftpClient.storeFile(fileName, inputStream);
            inputStream.close();
            ftpClient.logout();


            flag = true;
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (ftpClient.isConnected()) {
                try {
                    ftpClient.disconnect();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return flag;
    }


    /**
     * 上传文件（可对文件进行重命名）
     *
     * @param hostname       FTP服务器地址
     * @param port           FTP服务器端口号
     * @param username       FTP登录帐号
     * @param password       FTP登录密码
     * @param pathname       FTP服务器保存目录
